module adder_pipe_64bit
    (
        input clk,
        input rst_n,
        input i_en,
        input [64:1] adda,
        input [64:1] addb,
        output [65:1] result,
        output reg o_en
    );

    reg [15:1] adda_reg;
    reg [15:1] addb_reg;
    reg [15:1] adda_pipe1;
    reg [15:1] addb_pipe1;
    reg [15:1] adda_pipe2;
    reg [15:1] addb_pipe2;
    reg [15:1] adda_pipe3;
    reg [15:1] addb_pipe3;
    reg [15:1] adda_pipe4;
    reg [15:1] addb_pipe4;
    reg o_en_pipe1;
    reg o_en_pipe2;
    reg o_en_pipe3;
    reg o_en_pipe4;

    wire [16:1] adda_pipe1;
    wire [16:1] addb_pipe1;
    wire [16:1] adda_pipe2;
    wire [16:1] addb_pipe2;
    wire [16:1] adda_pipe3;
    wire [16:1] addb_pipe3;
    wire [16:1] adda_pipe4;
    wire [16:1] addb_pipe4;

    assign adda_pipe1 = {1'b0, adda};
    assign addb_pipe1 = {1'b0, addb};
    assign adda_pipe2 = {adda_pipe1[16:1], 1'b0};
    assign addb_pipe2 = {addb_pipe1[16:1], 1'b0};
    assign adda_pipe3 = {adda_pipe2[16:1], 1'b0};
    assign addb_pipe3 = {addb_pipe2[16:1], 1'b0};
    assign adda_pipe4 = {adda_pipe3[16:1], 1'b0};
    assign addb_pipe4 = {addb_pipe3[16:1], 1'b0};

    assign result = {adda_pipe4, addb_pipe4};

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            adda_reg <= 'd0;
            addb_reg <= 'd0;
            o_en_pipe1 <= 'd0;
        end
        else begin
            adda_reg <= adda;
            addb_reg <= addb;
            o_en_pipe1 <= i_en;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            adda_pipe1 <= 'd0;
            addb_pipe1 <= 'd0;
            o_en_pipe2 <= 'd0;
        end
        else begin
            adda_pipe1 <= adda_reg;
            addb_pipe1 <= addb_reg;
            o_en_pipe2 <= o_en_pipe1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            adda_pipe2 <= 'd0;
            addb_pipe2 <= 'd0;
            o_en_pipe3 <= 'd0;
        end
        else begin
            adda_pipe2 <= adda_pipe1;
            addb_pipe2 <= addb_pipe1;
            o_en_pipe3 <= o_en_pipe2;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            adda_pipe3 <= 'd0;
            addb_pipe3 <= 'd0;
            o_en_pipe4 <= 'd0;
        end
        else begin
            adda_pipe3 <= adda_pipe2;
            addb_pipe3 <= addb_pipe2;
            o_en_pipe4 <= o_en_pipe3;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            adda_pipe4 <= 'd0;
            addb_pipe4 <= 'd0;
            o_en <= 'd0;
        end
        else begin
            adda_pipe4 <= adda_pipe3;
            addb_pipe4 <= addb_pipe3;
            o_en <= o_en_pipe4;
        end
    end

endmodule

